    <p class="text-2xl italic leading-snug text-neutral-800">@Model.Quote</p>
    @if (!string.IsNullOrWhiteSpace(Model.Attribution))
    {
        <footer class="mt-3 text-sm text-neutral-500">@Model.Attribution</footer>
    }
</blockquote>

