@model Umbraco.Bench.Umbraco.Models.Blocks.RichTextBlockModel

<div class="space-y-4 text-lg leading-relaxed text-neutral-800 [&_a]:text-sky-700 [&_a]:underline">
    @Html.Raw(Model.Html)
</div>

@model Umbraco.Bench.Umbraco.Models.Blocks.ImageBlockModel

@if (Model.ImageUrl is not null)
{
    <figure class="my-8">
        <img src="@Model.ImageUrl" alt="@Model.Caption" class="w-full rounded-lg" loading="lazy" />
        @if (!string.IsNullOrWhiteSpace(Model.Caption))
        {
            <figcaption class="mt-2 text-sm text-neutral-500">@Model.Caption</figcaption>
        }
    </figure>
}

